# Frayd bootstrap (Windows) - generated by the web installer.
# Args: [-Lib LIBRARY_PATH] [-Tunnel tailscale|cloudflared]
param([string]$Lib = "", [string]$Tunnel = "")
$ErrorActionPreference = "Stop"
# Stop does not apply to native commands; check their exit codes explicitly.
function Assert-NativeSuccess([string]$Step) { if ($LASTEXITCODE -ne 0) { throw "$Step failed (exit $LASTEXITCODE)" } }
# winget exits nonzero when the package is already installed (0x8A150061) or has no newer version (0x8A15002B).
function Assert-WingetSuccess([string]$Step) { if ($LASTEXITCODE -notin 0, -1978335135, -1978335189) { throw "$Step failed (exit $LASTEXITCODE)" } }

Write-Host "== Frayd installer =="
Write-Host "Media folder: $(if ($Lib) { $Lib } else { '<unset>' })"

# --- deps ---
if (-not (Get-Command git -ErrorAction SilentlyContinue)) {
  Write-Host "[!] git is required: https://git-scm.com/download/win"; exit 1
}
if (-not (Get-Command ffmpeg -ErrorAction SilentlyContinue)) {
  Write-Host "[*] Installing ffmpeg via winget..."
  winget install -e --id Gyan.FFmpeg --accept-source-agreements --accept-package-agreements 2>$null
  Assert-WingetSuccess "winget install Gyan.FFmpeg"
}

# --- rust ---
if (-not (Get-Command cargo -ErrorAction SilentlyContinue)) {
  Write-Host "[*] Installing Rust toolchain..."
  Invoke-WebRequest https://win.rustup.rs/x86_64 -OutFile "$env:TEMP\rustup-init.exe"
  & "$env:TEMP\rustup-init.exe" -y --default-toolchain stable
  Assert-NativeSuccess "rustup-init"
  $env:PATH = "$env:USERPROFILE\.cargo\bin;$env:PATH"
}

# --- clone / update ---
Set-Location $env:USERPROFILE
if (Test-Path Frayd) { Push-Location Frayd; git pull --ff-only; Assert-NativeSuccess "git pull"; Pop-Location }
else { git clone https://github.com/kattiest/Frayd.git; Assert-NativeSuccess "git clone" }

# --- library path ---
if (-not $Lib) {
  $Lib = Read-Host "Path to your media folder [$env:USERPROFILE\Media]"
  if (-not $Lib) { $Lib = "$env:USERPROFILE\Media" }
}
New-Item -ItemType Directory -Force -Path $Lib | Out-Null
$Lib = (Resolve-Path -LiteralPath $Lib).ProviderPath

# --- build ---
Write-Host "[*] Building (first build takes a few minutes)..."
Set-Location Frayd\server
cargo build --release
Assert-NativeSuccess "cargo build"

# --- env file ---
# WriteAllText omits the UTF-8 byte order mark that would corrupt the first variable name.
[IO.File]::WriteAllText((Join-Path $PWD ".env"), @"
FRAYD_LIBRARY=$Lib
# Public internet exposure? Uncomment for shorter sessions (days):
# FRAYD_SESSION_DAYS=7
"@)

# --- remote access (optional) ---
if ($Tunnel -eq "tailscale") {
  Write-Host "`n== Tailscale remote access =="
  if (-not (Get-Command tailscale -ErrorAction SilentlyContinue)) {
    winget install -e --id tailscale.tailscale --accept-source-agreements --accept-package-agreements 2>$null
    Assert-WingetSuccess "winget install tailscale.tailscale"
  }
  Write-Host "[*] Launching Tailscale - log in in the window that opens."
  Start-Process "tailscale" "up" -ErrorAction SilentlyContinue
  $address = if (Get-Command tailscale -ErrorAction SilentlyContinue) { tailscale ip -4 2>$null }
  if ($LASTEXITCODE -eq 0 -and $address) { Write-Host "[OK] Your server's Tailscale address: $address  (or run: tailscale ip -4)" }
  else { Write-Host "[!] No Tailscale address yet - log in, then run: tailscale ip -4" }
  Write-Host "     Install Tailscale on your phone/laptop, same account, then open that address:8484"
} elseif ($Tunnel -eq "cloudflared") {
  Write-Host "`n== Cloudflare Tunnel remote access =="
  if (-not (Get-Command cloudflared -ErrorAction SilentlyContinue)) {
    winget install -e --id Cloudflare.cloudflared --accept-source-agreements --accept-package-agreements 2>$null
    Assert-WingetSuccess "winget install Cloudflare.cloudflared"
  }
  Write-Host "[*] Next steps (needs interactive login):"
  Write-Host "    cloudflared tunnel login; cloudflared tunnel create frayd"
  Write-Host "    cloudflared tunnel route dns frayd media.yourdomain.com"
  Write-Host "    cloudflared tunnel run frayd --url http://localhost:8484"
} else {
  Write-Host "`n[*] Local network only. Re-run installer with remote access ticked for Tailscale/Cloudflare."
}

# --- autostart: Startup folder shortcut (no admin needed) ---
$startup = [Environment]::GetFolderPath("Startup")
$bat = Join-Path $startup "frayd.bat"
# The startup script loads every uncommented .env line, as systemd does on Linux.
# The launcher is ASCII and finds the install through %USERPROFILE%; chcp 65001 makes cmd decode the UTF-8 .env.
@'
@echo off
chcp 65001 >nul
cd /d "%USERPROFILE%\Frayd\server"
for /f "usebackq eol=# tokens=*" %%a in (".env") do set "%%a"
start /b "" "%USERPROFILE%\Frayd\server\target\release\frayd-server.exe"
'@ | Out-File -Encoding ascii $bat

Write-Host ""
Write-Host "[OK] Frayd installed. Starting now..."
$env:FRAYD_LIBRARY = $Lib
Start-Process -FilePath "$PWD\target\release\frayd-server.exe" -WindowStyle Hidden
Write-Host "[OK] Runs at startup. Open http://localhost:8484"
Write-Host "     First login becomes the admin account."
